import torch

def _make(shape, dtype, device, seed):
    gen = torch.Generator(device='cpu').manual_seed(seed)
    info = torch.iinfo(dtype)
    low = max(int(info.min), -100000)
    high = min(int(info.max), 100000)
    t = torch.randint(low, high + 1, shape, generator=gen, dtype=dtype)
    flat = t.reshape(-1)
    if flat.numel() > 0:
        boundary = torch.tensor([0, -12, info.min, -27, 81, 6, 18, -9], dtype=dtype)
        n = min(flat.numel(), boundary.numel())
        flat[:n] = boundary[:n]
    return t.to(device)

def run(x, y):
    return torch.gcd(x, y)
